df_gas = pd.DataFrame(data_gas)
x_gas = df_gas[["Kilometers"]]
y_gas = df_gas[["Liters"]]
model_gas = LinearRegression()
model_gas.fit(x_gas, y_gas)

precio_por_litro = 15000

def calculateGasoline(km):
    prediction = model_gas.predict([[km]])
    litros = prediction[0][0]
    costo = litros * precio_por_litro
    return round(litros, 2), round(costo, 2)

def generarGraficaGasolina(km):
    prediction = model_gas.predict([[km]])
    litros = prediction[0][0]

    x_min = min(df_gas["Kilometers"].min(), km)
    x_max = max(df_gas["Kilometers"].max(), km)
    y_min = min(df_gas["Liters"].min(), litros)
    y_max = max(df_gas["Liters"].max(), litros)

    x_pad = (x_max - x_min) * 0.1 if x_max > x_min else 1
    y_pad = (y_max - y_min) * 0.1 if y_max > y_min else 1

    line_x = [x_min, x_max]
    line_y = model_gas.predict([[line_x[0]], [line_x[1]]])

    plt.figure(figsize=(6, 4))
    plt.scatter(df_gas["Kilometers"], df_gas["Liters"], color="#7fb08f", alpha=0.4, s=15, label="Training data")
    plt.plot(line_x, line_y, color="#e0a872", linewidth=2, label="Regression line")
    plt.scatter([km], [litros], color="#2f9e6f", s=100, zorder=5, label="Prediction")
    plt.xlim(x_min - x_pad, x_max + x_pad)
    plt.ylim(y_min - y_pad, y_max + y_pad)
    plt.xlabel("Kilometers")
    plt.ylabel("Liters")
    plt.title("Gasoline Consumption Prediction")
    plt.legend()

    img = io.BytesIO()
    plt.savefig(img, format='png')
    plt.close()
    img.seek(0)
    return base64.b64encode(img.getvalue()).decode('utf-8')